#include <fstream>
#include <iostream>
#include <string>

int main() {
    std::string first, second;
    if (!std::getline(std::cin, first)) return 1;
    if (!std::getline(std::cin, second)) return 1;
    if (first.size() > 100 || second.size() > 100) return 1;
    {
        std::ofstream out("lines.txt");
        if (!out) return 1;
        out << first << "\n";
        out << second << "\n";
    }
    std::ifstream in("lines.txt");
    if (!in) return 1;
    std::string line;
    int count = 0;
    std::string last;
    while (std::getline(in, line)) {
        count++;
        last = line;
    }
    std::cout << count << "\n";
    std::cout << last << "\n";
    return 0;
}
